### 参考代码

```cpp
// D. Magic Tiles
// 结论（已用 3^R 全枚举暴力验证）：
//   1) 最优解里每个黑格都会被选中（不给某列就归另一列）；
//   2) 两列线段的每个交集原子（两列都黑的极大行区间）整体归某一列。
// 于是把行轴切成「原子」：type=1 只能归列 1，type=2 只能归列 2，type=0 两列都可。
// 一列里连续的同类原子拼成一段「连续段」，答案就是所有连续段长度降序排列。
// 目标函数（100^{100^x}）等价于：把长度降序序列按字典序最大。
// DP：V[i][c] = 从原子 i 开始、且第 i 个原子所在连续段归属列 c 时，
//              后缀最优的「连续段长度降序表」。转移枚举本段在原子 j 处结束（j 之后
//              换另一列），值 = 把 W(i..j) 插入 V[j+1][3-c] 的降序表。
// 比较两个候选时惰性归并（不物化），只物化胜者。
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

// 原子 type 与列 c 是否相容（0 = 两列都黑，任意列都行）
static inline bool compat(int atomType, int c) { return atomType == 0 || atomType == c; }

// 比较「把 w1 插入降序表 T1」与「把 w2 插入降序表 T2」，true 表示前者字典序更大
static bool candBetter(ll w1, const vector<ll>& T1, ll w2, const vector<ll>& T2) {
    size_t i1 = 0, i2 = 0;
    bool u1 = false, u2 = false;
    while (true) {
        bool has1 = !(u1 && i1 >= T1.size());
        bool has2 = !(u2 && i2 >= T2.size());
        if (!has1 || !has2) return has1 && !has2;   // 前缀全等：更长者更大
        ll v1, v2;
        if (!u1 && (i1 >= T1.size() || w1 >= T1[i1])) { v1 = w1; u1 = true; }
        else v1 = T1[i1++];
        if (!u2 && (i2 >= T2.size() || w2 >= T2[i2])) { v2 = w2; u2 = true; }
        else v2 = T2[i2++];
        if (v1 != v2) return v1 > v2;
    }
}

// 把 w 插入降序表 T
static vector<ll> insertSorted(ll w, const vector<ll>& T) {
    vector<ll> r;
    r.reserve(T.size() + 1);
    size_t i = 0;
    while (i < T.size() && T[i] >= w) r.push_back(T[i++]);
    r.push_back(w);
    while (i < T.size()) r.push_back(T[i++]);
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tc;
    cin >> tc;
    while (tc--) {
        int n, m;
        cin >> n >> m;
        vector<pair<ll, ll>> seg1(n), seg2(m);
        for (auto& p : seg1) cin >> p.first >> p.second;
        for (auto& p : seg2) cin >> p.first >> p.second;
        sort(seg1.begin(), seg1.end());
        sort(seg2.begin(), seg2.end());

        // 端点扫描：把行轴切成「两列黑白状态都恒定」的原子
        vector<ll> pts;
        pts.reserve(2 * (n + m) + 2);
        for (auto& p : seg1) { pts.push_back(p.first); pts.push_back(p.second + 1); }
        for (auto& p : seg2) { pts.push_back(p.first); pts.push_back(p.second + 1); }
        sort(pts.begin(), pts.end());
        pts.erase(unique(pts.begin(), pts.end()), pts.end());

        vector<int> atype;      // 0 = 两列都黑，1 = 只有列 1，2 = 只有列 2，-1 = gap
        vector<ll> aw;
        size_t i1 = 0, i2 = 0;
        for (size_t k = 0; k + 1 < pts.size(); k++) {
            ll l = pts[k], r = pts[k + 1] - 1;
            if (l > r) continue;
            while (i1 < seg1.size() && seg1[i1].second < l) i1++;
            while (i2 < seg2.size() && seg2[i2].second < l) i2++;
            bool b1 = (i1 < seg1.size() && seg1[i1].first <= l && l <= seg1[i1].second);
            bool b2 = (i2 < seg2.size() && seg2[i2].first <= l && l <= seg2[i2].second);
            int tp = (b1 && b2) ? 0 : (b1 ? 1 : (b2 ? 2 : -1));
            if (!atype.empty() && atype.back() == tp) aw.back() += r - l + 1;
            else { atype.push_back(tp); aw.push_back(r - l + 1); }
        }

        vector<ll> ans;         // 所有连通块的连续段长度
        static const vector<ll> emptyT;
        int s = (int)atype.size();
        int st = 0;
        while (st < s) {
            if (atype[st] == -1) { st++; continue; }
            int en = st;
            while (en < s && atype[en] != -1) en++;      // 连通块 = [st, en)
            int len = en - st;
            // 块内局部下标 0..len-1
            // V[i][c]：i 局部下标，c = 1/2
            vector<array<vector<ll>, 3>> V(len);
            vector<array<char, 3>> ok(len);
            for (int i = 0; i < len; i++) { ok[i][1] = ok[i][2] = 0; }
            for (int i = len - 1; i >= 0; i--) {
                int ti = atype[st + i];
                for (int c = 1; c <= 2; c++) {
                    if (!compat(ti, c)) continue;
                    ll w = 0;
                    bool has = false;
                    ll bestW = 0;
                    const vector<ll>* bestT = nullptr;
                    for (int j = i; j < len && compat(atype[st + j], c); j++) {
                        w += aw[st + j];
                        bool feasible;
                        const vector<ll>* tail;
                        if (j + 1 == len) { feasible = true; tail = &emptyT; }
                        else if (compat(atype[st + j + 1], 3 - c)) {
                            feasible = true; tail = &V[j + 1][3 - c];
                        } else feasible = false;
                        if (!feasible) continue;
                        if (!has || candBetter(w, *tail, bestW, *bestT)) {
                            has = true; bestW = w; bestT = tail;
                        }
                    }
                    if (has) {
                        V[i][c] = insertSorted(bestW, *bestT);
                        ok[i][c] = 1;
                    }
                }
            }
            // 连通块答案：第一个原子的相容列里取更优者
            int bestc = 0;
            for (int c = 1; c <= 2; c++) {
                if (!ok[0][c]) continue;
                if (bestc == 0 || V[0][c] > V[0][bestc]) bestc = c;
            }
            for (ll v : V[0][bestc]) ans.push_back(v);
            st = en;
        }
        sort(ans.rbegin(), ans.rend());
        cout << ans.size() << "\n";
        for (size_t k = 0; k < ans.size(); k++) cout << ans[k] << " ";
        cout << "\n";
    }
    return 0;
}
```

### 易错点

一行两格都黑时仍只能选一格，不能说“每个黑格都选”。压缩段长度、端点及其和用 64 位整数。

## E. DivMEX

### 题意

对每个子数组，取最小的不整除该子数组最小公倍数的正整数。输出所有可能结果，去重升序。保证 $a_i\le n$。

<!-- reusable-foundations:start -->

### 从零讲：整除、最大公约数与质因数

正整数 $d$ 整除 $n$，表示 $n$ 能分成整数个大小为 $d$ 的组，即 `n % d == 0`。公约数同时整除两个数，其中最大者为最大公约数。欧几里得算法使用 $\gcd(a,b)=\gcd(b,a\bmod b)$，因为共同整除两者的数也恰好整除余数。

例如 $\gcd(18,12)=\gcd(12,6)=\gcd(6,0)=6$。每两轮较大参数至少缩半，故为 $O(\log\max(a,b))$。C++17 `<numeric>` 提供 `gcd`；最小公倍数可按 `a/gcd(a,b)*b` 计算以减少中间量，但最终乘积仍须检查范围。

质数是大于一、只有一和自身两个正因数的整数，一不是质数。合数一定有不超过平方根的质因数：若一对因数都超过平方根，乘积会大于原数。因此试除只需检查到平方根。

```cxx
vector<pair<long long,int>> factor(long long n) {
    vector<pair<long long,int>> result;
    for (long long p = 2; p <= n / p; ++p) {
        if (n % p != 0) continue;
        int exponent = 0;
        while (n % p == 0) { n /= p; ++exponent; }
        result.push_back({p, exponent});
    }
    if (n > 1) result.push_back({n, 1});
    return result;
}
```

正整数六十拆成 $2^2\times3\times5$。每个因子的指数可从零选到其最大次数，所以因数数量为 $(2+1)(1+1)(1+1)=12$。剩余大于一的部分必须作为一个质因数保留。条件 `p<=n/p` 避免为检查平方而溢出。

试除最坏约 $O(\sqrt n)$。要处理从一到 $N$ 的大量质数问题，可用筛法：埃氏筛从每个质数的平方起标记倍数，时间 $O(N\log\log N)$、空间 $O(N)$。线性筛额外维护最小质因子，使每个合数只由规定的一次生成；不能把任意双循环标倍数都称为线性筛。

### 从零讲：线段树：把区间问题分成可合并的两半

需要动态修改并查询区间的和、最小值或最大值时，可以递归将数组一分为二。一个节点代表一段范围，叶子代表单个元素，父节点保存两个孩子答案的合并。

![四项数组的区间树，整段答案来自左右两半](assets/foundations/segment-tree.svg)

例如 $[2,3,1,4]$，叶子是各项，左半和五、右半和五，根为十。修改第三项后，只需改叶子及其到根的祖先；其他范围完全未变。查询 $[2,3]$ 时取覆盖这两项的节点，跳过完全无交的节点，合并各部分。

树高 $O(\log n)$。单点修改沿一条根到叶路径，区间查询在每层只需处理边界附近的少量分支，均为 $O(\log n)$；建树 $O(n)$，空间 $O(n)$，数组式常预留约四倍大小。

```cxx
// 假设当前结点范围为 [left,right]，查询为 [ql,qr]
if (ql <= left && right <= qr) return tree[node];
int mid = left + (right - left) / 2;
long long answer = 0; // 求和的合并单位；求最小值应换成 +INF
if (ql <= mid) answer += query(node*2, left, mid, ql, qr);
if (qr > mid) answer += query(node*2+1, mid+1, right, ql, qr);
return answer;
```

求和、求最小和最大各有自己的合并与无交单位，不能混用。维护的信息要足以从孩子合并；例如最大连续子段和需要额外的区间和、最大前缀及后缀，单存一个最大值不够。

区间修改可用懒标记：整段更新时先改当前节点答案，记录尚未作用到孩子的操作；下次进入孩子前下传。区间加对区间和的变化是“增量乘长度”，赋值与加法的标记组合顺序不同。只有更新能够从所存摘要直接计算、且标记能正确复合时才能这样优化，不能对任意操作机械加一个 lazy 数组。

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cxx
for (int i = 0; i < n; ++i)
    for (int j = i + 1; j < n; ++j) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

### 从零讲：lower_bound 与 upper_bound：从位置到数量

#### 什么时候使用

有一批可以比较大小的数据，需要反复问“小于某数的有几个”“某个值出现几次”“第一个达到要求的元素在哪”。先排序，再查边界，能避免每次从头扫描。这里先讨论从小到大的 `vector<int>`，头文件为 `<algorithm>` 和 `<vector>`，适用于 C++17。

#### 先弄清返回的是什么

`a.begin()` 指向第一个元素，`a.end()` 指向末元素之后的空位置。`[a.begin(), a.end())` 包含左端、不包含右端。迭代器可以理解为指向容器中某个位置的标记；它不是元素的值，也不是数量。

设有序数组为 $[1,2,2,2,5,8]$，下标从零开始，查询 $x=2$：

![相等元素位于两条边界之间，边界位置之前的格子数就是计数](assets/foundations/bounds.svg)

- `lower_bound(a.begin(), a.end(), x)` 返回第一个**大于等于** `x` 的位置，这里是下标一。
- `upper_bound(a.begin(), a.end(), x)` 返回第一个**严格大于** `x` 的位置，这里是下标四。

把名字与等号绑定记忆：`lower_bound` 是相等区间的左边界，`upper_bound` 是相等区间的右边界；没有相等元素时两条边界重合。两个函数均不保证命中 `x`。

```cxx
vector<int> a{1, 2, 2, 2, 5, 8};
int x = 2;
auto lo = lower_bound(a.begin(), a.end(), x);
auto hi = upper_bound(a.begin(), a.end(), x);
int less = int(lo - a.begin());          // 1 个元素 < 2
int lessEqual = int(hi - a.begin());     // 4 个元素 <= 2
int equal = int(hi - lo);                // 3 个元素 == 2
```

#### 为什么“位置减 begin”可以计数

`lo` 之前恰有下标 $0$ 到 $0$ 的一个元素。一般地，第一个大于等于 $x$ 的位置如果是 $k$，它前面的下标为 $0,1,\ldots,k-1$，恰有 $k$ 个；有序性保证这 $k$ 个全部严格小于 $x$，之后没有漏下的小数。对 `vector`，`lo-a.begin()` 就是跨过的格子数 $k$。

同理，`hi` 之前全部不大于 $x$，所以它的下标就是不大于 $x$ 的数量。令数组长度为 $n$，便有：

| 要统计的元素 | C++ 表达式 | 本例结果 |
|---|---|---|
| 小于 $x$ | `lo - a.begin()` | $1$ |
| 不大于 $x$ | `hi - a.begin()` | $4$ |
| 大于等于 $x$ | `a.end() - lo` | $5$ |
| 大于 $x$ | `a.end() - hi` | $2$ |
| 等于 $x$ | `hi - lo` | $3$ |

因此，函数本身找的是分界位置，计数来自分界两边的长度。查询闭区间 $[L,R]$ 中的数量（保证 $L\le R$），用 `upper_bound(..., R)-lower_bound(..., L)`；这也避免了写 `L-1` 时可能发生的整数下溢。

#### 底层怎样二分

下面返回下标，展示 `lower_bound` 的核心逻辑，不依赖库函数：

```cxx
int first_ge(const vector<int>& a, int x) {
    int left = 0, right = int(a.size());
    // 答案在位置 [left, right] 内；待判断元素在 [left, right)。
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (a[mid] < x) left = mid + 1;
        else right = mid;
    }
    return left;  // 可以等于 a.size()，表示没有符合条件的元素
}
```

若中点小于 $x$，它左侧都小于 $x$，连同中点一起排除；否则答案不会在中点右侧，把右边界移到中点，保留中点本身作为可能答案。每次排除约一半候选，区间长度从 $n$ 变成约 $n/2,n/4,\ldots$，经过约 $\log_2 n$ 次就剩一个边界，所以时间为 $O(\log n)$，额外空间为 $O(1)$。

实现 `upper_bound` 时，把 `a[mid] < x` 改为 `a[mid] <= x`：遇到相等也继续向右，才能越过全部重复值。比如六个数查二，`lower_bound` 的左边界、右边界和中点三个下标依次为 $(0,6,3)$、$(0,3,1)$、$(0,1,0)$，最终返回一；`upper_bound` 依次为 $(0,6,3)$、$(4,6,5)$、$(4,5,4)$，最终返回四。

#### 使用条件和边界

第一次排序花 $O(n\log n)$，之后 $q$ 次查询共花 $O(q\log n)$。每次查询前都重新排序，会丢掉复用有序数组的优势。若还需要原来的配对、编号或顺序，应另存原数据，再排序供查询的副本。

查零时两条边界都在 `begin()`；查十时都在 `end()`；查三时都指向五。空数组也会返回 `end()`，计数自然为零。**可以拿 `end()` 计算长度，不能解引用它。** 查是否存在应写 `it != a.end() && *it == x`。

一般前提是比较条件能把范围分成两段；完整升序是最易保证的方式。普通乱序数组不能直接套用。降序或自定义排序必须使用匹配的比较器，不能沿用上表的自然大小解释。

`vector`、数组的随机访问迭代器支持常数时间跳到中点和相减，所以总时间为 $O(\log n)$。`list` 或 `set` 的迭代器不支持相减，通用二分虽然比较次数是对数，迭代器移动却可能达到线性；在 `set`、`map` 上优先用成员函数 `s.lower_bound(x)`、`s.upper_bound(x)`，它们沿树查找为 $O(\log n)$。成员函数得到的迭代器到 `begin()` 的距离仍未必能快速计算。

规范核对：[C++ 工作草案：二分边界算法](https://eel.is/c++draft/alg.binary.search)。本文只使用 C++17 已有接口。

### 从零讲：lambda：定义、捕获和调用一个局部函数

#### 它解决什么问题

一段操作在当前函数里需要调用多次，或者某个算法需要你提供“怎样比较”的规则，可以把这段操作写成 lambda。lambda 表达式产生一个可以像函数一样调用的对象；“匿名”指它没有普通函数声明中的函数名，仍可以用变量保存并命名。

```cxx
auto add = [](int a, int b) -> int {
    return a + b;
};
int answer = add(2, 3);  // 调用后得到 5；定义本身不会执行函数体
```

读法是：用 `auto` 保存对象；`[]` 是捕获列表；圆括号是每次调用传入的参数；`-> int` 指定返回类型；花括号里写执行过程；定义后的分号结束赋值。返回类型能够推导时可省略，所以也常见 `auto add = [](int a,int b) { return a+b; };`。

![参数在调用时传入，捕获连接定义位置可见的外部变量](assets/foundations/lambda.svg)

#### 参数和捕获有什么区别

参数每次调用都由调用者提供；捕获让函数体使用定义位置附近的局部变量，调用时不用重复传它。例如阈值来自当前环境，待判断的值每次变化：

```cxx
int threshold = 10;
auto enough = [threshold](int value) {
    return value >= threshold;
};
bool a = enough(12);  // true，value 是本次传入的 12
```

这里 `threshold` 是捕获，`value` 是参数。常用的捕获方式如下：

| 写法 | 意思 | 适合的需要 |
|---|---|---|
| `[]` | 不捕获局部变量 | 只依赖参数的计算或比较 |
| `[x]` | 保存定义时 `x` 的副本 | 需要固定一份快照 |
| `[&x]` | 引用外面的 `x` | 读取最新值或修改原变量 |
| `[=]` | 按值捕获实际需要的局部变量 | 需要多个快照 |
| `[&]` | 按引用捕获实际需要的局部变量 | 当前作用域内的辅助函数 |
| `[&a, limit]` | 引用 `a`，复制 `limit` | 显式区分共享数据和快照 |

`[&]` 不是“把参数按引用传递”；是否按引用传参由圆括号里的 `int&`、`const vector<int>&` 等类型决定。全局变量可以直接访问，无需捕获。

#### 用可观察的结果区分复制与引用

```cxx
int base = 10;
auto snapshot = [base](int x) { return base + x; };
auto current = [&base](int x) { return base + x; };
base = 20;
int a = snapshot(1);  // 11：使用定义时保存的 10
int b = current(1);   // 21：使用外面的最新值 20
```

默认情况下不能在 lambda 内修改按值捕获的副本。加 `mutable` 才能修改副本，但仍不会改外面的原变量：`auto next = [base]() mutable { return ++base; };`。对大数组按值捕获可能复制整个数组；如果只在数组仍然存活时查询，显式引用可避免这份复制。

#### 两种常见用法

**局部辅助函数。** 把“给一个参数就求出结果”的操作命名后，主流程只写调用。外层数组保持原处，辅助函数按引用读取，能减少重复代码，并让环境依赖集中在定义附近。对多个调用位置修正一处逻辑即可。普通独立函数也能做到复用，但外层局部数据通常需要显式传参。

**作为算法的规则。** 把比较方式直接交给 `sort`，能在调用处看到排序依据：

```cxx
sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
    if (a.first != b.first) return a.first < b.first;
    return a.second > b.second;
});
```

先按第一项升序，第一项相同时按第二项降序。比较器必须形成严格弱序，同一个元素与自己比较应为假；写成 `<=` 可能破坏排序前提。传 `const auto&` 可以避免每次比较都复制元素。

#### 递归时怎样引用自己

在 `auto f = ...` 的初始化表达式中不能直接假定 `f` 的类型已确定。C++17 可以把自己作为参数传进去：

```cxx
auto factorial = [](auto&& self, int n) -> long long {
    if (n <= 1) return 1;
    return n * self(self, n - 1);
};
long long value = factorial(factorial, 5);  // 120
```

也可先声明 `std::function<long long(int)> f` 再赋 lambda，通过引用调用 `f`；需要 `<functional>`。`std::function` 用统一类型包装可调用对象，便于存储和传递，但可能有间接调用、分配等额外开销。只在当前地方使用时，`auto` 常更直接。这些是组织代码的选择，不会改变原算法的复杂度。

#### 生命周期和复杂度

引用捕获不会延长被引用变量的生命。把引用局部数组的 lambda 返回到函数外，局部数组已经销毁，再调用就会访问失效对象；放入异步任务或长久保存时，也须检查这一点。必要时捕获一份拥有数据的副本，或设计明确的共享所有权。

调用一次 lambda 的时间取决于函数体：内部扫描 $n$ 个元素就是 $O(n)$，做两次有序数组二分就是 $O(\log n)$。创建时复制大容器还会有与数据量相关的成本。lambda 的优势是局部表达、复用和传递行为，本身不保证运行更快。

规范核对：[C++ 工作草案：捕获](https://eel.is/c++draft/expr.prim.lambda.capture)、[函数对象](https://eel.is/c++draft/function.objects)。示例均为 C++17 写法。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：pair、tuple 与结构化绑定

有些数据天然需要成组：一个区间有两个端点，一个队列状态有坐标和距离。`pair<A,B>` 保存两项，用 `.first`、`.second` 读取；`tuple<A,B,C>` 可保存更多项，用 `get<0>(t)` 等读取。分别需要 `<utility>`、`<tuple>`。

C++17 的结构化绑定能为一组分量起局部名字：

```cxx
pair<int,int> point{3, 5};
auto [x, y] = point;      // 复制出两个分量
x = 9;                  // point.first 仍为 3
auto& [u, v] = point;    // 绑定原对象的分量
u = 7;                  // point.first 变为 7
```

`for (auto [l,r] : segments)` 每轮读取一对值；`for (const auto& [l,r] : segments)` 以只读引用读取，避免复制；需要修改原记录时才用 `auto&`。引用必须在原对象还存在且位置未失效时使用。

`pair` 和 `tuple` 的默认比较是字典序：从第一项起，第一个不同的分量决定顺序。`priority_queue<pair<int,int>>` 因而先比较第一项，再以第二项破同分，不能误认为只看第一项。这类语法只让记录组织和访问更清楚，拆分本身的成本取决于分量是否需要复制。

### 从零讲：sort 与比较器：先建立统一的顺序

排序把原来任意排列的数据，按照可比较的键整理成有序序列，便于查边界、比较相邻项和按顺序处理。头文件 `<algorithm>`；普通数组和 `vector` 可用 `sort(first,last)`，范围为左闭右开。

```cxx
vector<int> a{5, 2, 5, 1};
sort(a.begin(), a.end());     // 变成 1、2、5、5，重复值仍保留
sort(a.begin(), a.end(), greater<int>());  // 降序
```

`sort` 时间 $O(n\log n)$，不是每次比较都扫描整个数组。C++ 标准规定复杂度要求，不规定必须使用某一固定内部排序实现，不能统一称它为快速排序。

对 `pair`，默认先比较 `first`，相同再比较 `second`，都是升序。自定义比较器 `cmp(a,b)` 返回真表示“$a$ 必须排在 $b$ 前面”。例如按分数降序、同分按编号升序：

```cxx
sort(students.begin(), students.end(), [](const auto& a, const auto& b) {
    if (a.score != b.score) return a.score > b.score;
    return a.id < b.id;
});
```

规则必须自洽：元素不能排在自己前面，不能出现 $a$ 在 $b$ 前、$b$ 在 $c$ 前、$c$ 又在 $a$ 前的循环。`<=` 会让相同元素也必须互相在前，因此不是合法的严格比较器。排序过程中也不能改变比较依据。

排序会改变原位置；若编号或两项的配对有意义，应将完整记录一起排序或另存查询副本，不能把两个相关字段各自排序后继续当作原配对。普通 `sort` 不保证同键元素保持输入先后；确需稳定顺序时用 `stable_sort` 或将原编号纳入比较键。排序只建立顺序，不能代替贪心策略的正确性证明。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

### 从零讲：迭代器、begin/end 与左闭右开范围

迭代器表示容器中的一个位置。`*it` 读取它指向的元素，`++it` 向后移动，`it == c.end()` 判断是否已经到尾后。把末尾之后的位置作为边界，使空范围、整个容器和一段子区间都能用同一形式表示。

```cxx
vector<int> a{4, 7, 9};
for (auto it = a.begin(); it != a.end(); ++it) {
    cout << *it << ' ';   // 输出 4 7 9
}
```

`[first,last)` 包含 `first`，排除 `last`。`[begin,begin)` 是空范围，`[begin,end)` 包含所有元素。不能读取 `*end()`；找不到时返回 `end()` 是合法结果，必须先判断再读取。

数组和 `vector` 的迭代器支持随机访问：`begin()+k` 跳到下标 $k$，`it-begin()` 得到下标，均为 $O(1)$。例如指向下标二的位置之前有零、一两个元素，故减起点也能表示前面有几个数。相减只对同一容器中可相减的迭代器有效。

`list`、`set`、`map` 的迭代器通常只能逐步移动，不支持 `it-begin()`。`distance(begin,it)` 可以计算距离，但在这些容器上需要走过中间位置，时间为 $O(k)$；不能因为写了一个函数就认为它是常数时间。

容器修改后，旧位置可能失效：`vector` 扩容会使旧位置失效，删除元素会影响该处及其后位置。需要跨修改保存“第几个”时可保存下标，再按新数据重新取得迭代器，同时核对下标是否仍然合法。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cxx
unsigned long long mask = 5; // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

<!-- reusable-foundations:end -->

### 从零讲：$f(l,r)$ 一定是素数幂

设最小的不整除某个数 $L$ 的正整数是 $q$。如果 $q$ 含至少两个互异素因子，可以拆成互质的真因子 $u,v<q$；由最小性它们都整除 $L$，于是 $uv=q$ 也整除 $L$，矛盾。所以 $q$ 必是一个素数的幂。

再看 $q=p^e$。区间最小公倍数中 $p$ 的指数，是区间各元素中该指数的最大值，所以只需存在一个元素含至少 $e$ 个因子 $p$，等价于出现 $q$ 的倍数。

例如 $[2,3]$ 的最小公倍数为六：素数幂二、三都出现倍数，四没有，因此答案为四。无需真的计算容易溢出的最小公倍数，只需维护各素数幂有没有出现倍数。

### 思路

数组 $[2,3,4]$ 中，区间 $[2,3]$ 的最小公倍数为六，最小不整除它的数是四；整个数组的最小公倍数为十二，答案则为五。扩张区间会补齐缺少的因子，所以同一个候选值需要寻找“始终缺它、却不缺更小值”的区间。

#### 从最小公倍数转成素数幂是否出现

答案必是素数幂。若最小缺失数含两个不同素因子，可以拆成两个互质的真因子；这两个更小的数都整除最小公倍数，则其乘积也整除，产生矛盾。对于素数幂 $q=p^e$，它整除一个区间的最小公倍数，恰好等价于区间中出现了 $q$ 的倍数，因为最小公倍数对每个素因子取最大指数。

因此只需考虑按大小排列的素数幂。由于 $a_i\le n$，令 $\rho$ 为第一个大于 $n$ 的素数幂，它的倍数不可能出现，任何区间答案都不超过 $\rho$。

#### 只保存极大的缺席区间

对每个候选 $q$，记录数组中所有 $q$ 倍数的位置。相邻位置之间、以及首尾两侧，构成极大的“不含 $q$ 倍数”的非空区间，给它们标上归属者 $q$。

如果某个子数组的答案为 $q$，将它向两边扩张到这样的极大间隙，仍然缺少 $q$，而已经存在的更小素数幂倍数不会消失，答案仍为 $q$。所以只需判断这些间隙，无需枚举全部子数组。

按素数幂从小到大扫描。处理当前值 $r$ 时，把所有完全包含在某个 $r$ 缺席间隙内的尚存候选区间删去。一个候选第一次被删除的时刻，正是它最小缺失的素数幂。如果它的归属者也为 $r$，就得到一个答案为 $r$ 的见证；若归属者更大，说明它过早缺少了较小值，不能作为自己归属者的见证。

只检查归属者相等不会漏答案：任何真正可达的 $q$，都有一个归属 $q$ 的极大间隙，其内含所有更小素数幂的倍数，必能存活到第 $q$ 步才被删除。

#### 用线段树把“包含删除”变成一次性工作

将候选按左端点 $L$ 分组，组内按右端点升序排列，指针指向第一个尚存候选。线段树在每个左端点处存当前最小右端点。要删除被 $[l,r]$ 包含的候选，只需找 $L\ge l$ 且组内最小右端点不超过 $r$ 的叶子；取出一个候选，移动指针并更新，直到再也找不到。

不必另加 $L\le r$ 的条件，因为合法候选总有 $L\le R$，而已要求 $R\le r$。每个候选只会被删除一次，失败查询的次数也不超过扫描间隙数。一个元素最多向 $O(\log n)$ 个素数幂贡献倍数位置，所以候选总量 $S=O(n\log n)$；排序与删除的总时间为 $O(S\log S)$，空间为 $O(n+S)$。分解元素时需登记每个质因子的所有幂次，不能只登记最高次幂。

### 参考代码

```cpp
// E. DivMEX
// 结论：f(l,r) 一定是素数幂。x = p^e 可行 <=> 存在一段「不含 x 的倍数的极大区间」，
// 该区间内每个小于 x 的素数幂都有倍数出现。
// 做法：把每个素数幂 q 的「无 q 倍数极大区间」收集起来（共 O(n log n) 段），
// 按 q 从小到大扫描：第 q 步把落在「无 q 倍数区间」内的存活区间判死，
// 若某个死掉区间的归属者正好是 q，则 q 可行。用线段树（按左端点存最右端点最小值）加速删除。
#include <bits/stdc++.h>
using namespace std;

static const int MAXV = 205000;      // n <= 2e5，答案不超过「比 n 大的最小素数幂」
static const int INF = INT_MAX;

int spf[MAXV + 1];                   // 最小质因子
vector<int> ppList;                  // 所有 <= MAXV 的素数幂，升序

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // 线性筛
    {
        vector<int> primes;
        for (int i = 2; i <= MAXV; i++) {
            if (!spf[i]) { spf[i] = i; primes.push_back(i); }
            for (int p : primes) {
                if ((long long)p * i > MAXV || p > spf[i]) break;
                spf[p * i] = p;
            }
        }
        for (int p : primes)
            for (long long v = p; v <= MAXV; v *= p) ppList.push_back((int)v);
        sort(ppList.begin(), ppList.end());
    }

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n + 1);
        for (int i = 1; i <= n; i++) cin >> a[i];

        // rho = 大于 n 的最小素数幂；答案值 x 必 <= rho
        int rho = *lower_bound(ppList.begin(), ppList.end(), n + 1);
        int K = (int)(upper_bound(ppList.begin(), ppList.end(), rho) - ppList.begin());

        // D[q]：a_i 是 q 的倍数的位置，升序
        vector<vector<int>> D(rho + 1);
        for (int i = 1; i <= n; i++) {
            int x = a[i];
            while (x > 1) {
                int p = spf[x], e = 0;
                while (x % p == 0) { x /= p; e++; }
                long long v = p;
                for (int k = 1; k <= e; k++, v *= p)
                    if (v <= rho) D[(int)v].push_back(i);   // 只看候选素数幂
            }
        }

        // 每个素数幂 q 的极大「无 q 倍数区间」[L,R]，归属者 q，按 L 归档
        vector<vector<pair<int, int>>> byL(n + 1);   // byL[L] = {(R, owner)}，按 R 升序
        for (int idx = 0; idx < K; idx++) {
            int q = ppList[idx];
            int prev = 0;
            for (int d : D[q]) {
                if (prev + 1 <= d - 1) byL[prev + 1].push_back({d - 1, q});
                prev = d;
            }
            if (prev + 1 <= n) byL[prev + 1].push_back({n, q});
        }

        int sz = 1;
        while (sz < n) sz <<= 1;
        vector<int> seg(2 * sz, INF);
        vector<int> ptr(n + 1, 0);
        for (int L = 1; L <= n; L++) {
            sort(byL[L].begin(), byL[L].end());
            if (!byL[L].empty()) seg[sz + L - 1] = byL[L][0].first;
        }
        for (int i = sz - 1; i >= 1; i--) seg[i] = min(seg[2 * i], seg[2 * i + 1]);

        // 找 L >= a 且当前最小 R <= b 的叶子；没有返回 -1
        auto findLeaf = [&](auto&& self, int node, int l, int r, int a, int b) -> int {
            if (r < a || seg[node] > b) return -1;
            if (l == r) return l;
            int mid = (l + r) >> 1;
            int res = self(self, 2 * node, l, mid, a, b);
            if (res != -1) return res;
            return self(self, 2 * node + 1, mid + 1, r, a, b);
        };
        auto refresh = [&](int L) {
            int node = sz + L - 1;
            seg[node] = (ptr[L] < (int)byL[L].size()) ? byL[L][ptr[L]].first : INF;
            for (node >>= 1; node >= 1; node >>= 1)
                seg[node] = min(seg[2 * node], seg[2 * node + 1]);
        };

        vector<char> ok(rho + 1, 0);
        for (int idx = 0; idx < K; idx++) {
            int r = ppList[idx];
            int prev = 0;
            int cnt = (int)D[r].size();
            for (int j = 0; j <= cnt; j++) {
                int a0 = prev + 1;
                int b0 = (j < cnt) ? D[r][j] - 1 : n;
                if (a0 <= b0) {
                    while (true) {
                        int L = findLeaf(findLeaf, 1, 1, sz, a0, b0);
                        if (L == -1) break;
                        int owner = byL[L][ptr[L]].second;
                        ptr[L]++;
                        refresh(L);
                        if (owner == r) ok[r] = 1;   // 该区间恰好在第 r 步判死 => f 值可达 r
                    }
                }
                if (j < cnt) prev = D[r][j];
            }
        }

        vector<int> ans;
        for (int idx = 0; idx < K; idx++)
            if (ok[ppList[idx]]) ans.push_back(ppList[idx]);
        cout << ans.size() << "\n";
        for (size_t i = 0; i < ans.size(); i++) cout << ans[i] << " ";
        cout << "\n";
    }
    return 0;
}
```

### 易错点

只记录每个素因子的最高次幂会漏掉较低幂的倍数位置。空缺席间隙不构成子数组，不能当见证。

## F. Plus Minus Tree

### 题意

有根树结点取值为 $-1,0,1$，把所有零独立改成正一或负一，最小化所有结点的“子树权值和绝对值”之和。

<!-- reusable-foundations:start -->

### 从零讲：树的根、子树、DFS 序与倍增

树是连通且无环的无向图，$n$ 个顶点有 $n-1$ 条边。指定一个根后，每个非根顶点有唯一父亲，其他向下邻居是孩子。子树包含自己和全部后代；换根会改变父子关系，但不改变原边。

![同一棵树选定根后，圈出的子树包含节点自己及其全部后代](assets/foundations/trees.svg)

#### 子树信息按依赖顺序计算

例如子树大小 `size[u]` 初始为一，每个孩子处理完后累加 `size[v]`。一来自节点自己，不能漏掉。树形 DP 也如此：先明确某状态允许怎样选择，再合并各孩子提供的信息；孩子独立性来自树上没有跨子树边，仍可能因总预算或选中父亲等条件产生状态关联。

换根 DP 先求一个根的状态，再沿边换根，将“来自孩子的一侧”和“来自父亲的一侧”合并。应画清只有哪条边的方向改变、哪些量不变；不能仅凭两张答案表代替依赖解释。普通遍历每条边常数次为 $O(n)$，背包式合并可能更大，按实际合并循环计算。

#### DFS 序为什么能把子树变成区间

进入节点时分配编号 `tin[u]`，完成整棵子树后记录最后编号 `tout[u]`。深度优先在返回父亲前会完整处理这棵子树，因此它的所有编号连续，恰是 $[tin[u],tout[u]]$。这允许把子树和等查询交给数组结构。若同时记录进出事件，区间定义会不同，不可混用两种序列。

#### 倍增与最近公共祖先

`up[k][u]` 存 $u$ 向上 $2^k$ 条边到达的祖先。基础 `up[0][u]=parent[u]`，递推为 `up[k][u]=up[k-1][up[k-1][u]]`，因为连续走两段 $2^{k-1}$。跳十三层可拆为八加四加一，只需对数个跳跃。

LCA 是两个节点公共祖先中最深者。先把更深的一方跳到同深度；若已经相同就是答案。否则从大到小试跳，祖先不同才两边同时上移，最后它们的父亲就是 LCA。预处理 $O(n\log n)$、每次查询 $O(\log n)$，表空间 $O(n\log n)$。根的虚拟祖先需统一定义，不能访问非法下标。

树的直径在非负无权边长等常见条件下可用两次最远点搜索求出；带负权时要重新判断。虚树则将关注节点按 DFS 序组织，补上相邻节点的 LCA 后连接祖先关系，边应携带原路径含义，不能把压缩后一条边误当原图一步。深链上的递归也须留意栈深度。

### 从零讲：差分：把区间的变化写在两个边界

很多次操作都给一整段加同一个数，最后才需要所有位置的结果。逐项修改会重复扫描；差分只记录“从哪里开始多这一份、从哪里停止”。

定义 $D_1=a_1$，$D_i=a_i-a_{i-1}$。从左累计 $D$ 就能恢复 $a$。给闭区间 $[l,r]$ 加 $v$，仅需 $D_l$ 加 $v$、$D_{r+1}$ 减 $v$：第 $l$ 位开始，前缀多出 $v$；到第 $r+1$ 位，额外的一份被抵消。

![第 2 位开始加三，第 5 位停止；只有第 2 至 4 位被改变](assets/foundations/difference.svg)

例如五个零上给 $[2,4]$ 加三，差分事件为 $[0,3,0,0,-3]$，累计得到 $[0,3,3,3,0]$。两个标记不表示只修改了两个原元素。

```cxx
vector<long long> d(n + 2, 0);
d[l] += v;
d[r + 1] -= v;
long long current = 0;
for (int i = 1; i <= n; ++i) {
    current += d[i];
    // current 是该位置受到的总增量
}
```

$q$ 次区间加与最后恢复共 $O(n+q)$，空间 $O(n)$。如果初始数组非零，可先构造它的差分，或在恢复增量后加回原值。右边界要标在后一位，数组须留出 `n+1`；闭区间和半开区间的停止位置不能混用。

差分适合离线集中恢复。若每次操作后立刻查询任意位置，仅存差分并不能自动做到常数时间，需要动态前缀数据结构。坐标非常大但事件少时，应排序事件或离散化，不能按最大坐标盲目分配数组。

### 从零讲：sort 与比较器：先建立统一的顺序

排序把原来任意排列的数据，按照可比较的键整理成有序序列，便于查边界、比较相邻项和按顺序处理。头文件 `<algorithm>`；普通数组和 `vector` 可用 `sort(first,last)`，范围为左闭右开。

```cxx
vector<int> a{5, 2, 5, 1};
sort(a.begin(), a.end());     // 变成 1、2、5、5，重复值仍保留
sort(a.begin(), a.end(), greater<int>());  // 降序
```

`sort` 时间 $O(n\log n)$，不是每次比较都扫描整个数组。C++ 标准规定复杂度要求，不规定必须使用某一固定内部排序实现，不能统一称它为快速排序。

对 `pair`，默认先比较 `first`，相同再比较 `second`，都是升序。自定义比较器 `cmp(a,b)` 返回真表示“$a$ 必须排在 $b$ 前面”。例如按分数降序、同分按编号升序：

```cxx
sort(students.begin(), students.end(), [](const auto& a, const auto& b) {
    if (a.score != b.score) return a.score > b.score;
    return a.id < b.id;
});
```

规则必须自洽：元素不能排在自己前面，不能出现 $a$ 在 $b$ 前、$b$ 在 $c$ 前、$c$ 又在 $a$ 前的循环。`<=` 会让相同元素也必须互相在前，因此不是合法的严格比较器。排序过程中也不能改变比较依据。

排序会改变原位置；若编号或两项的配对有意义，应将完整记录一起排序或另存查询副本，不能把两个相关字段各自排序后继续当作原配对。普通 `sort` 不保证同键元素保持输入先后；确需稳定顺序时用 `stable_sort` 或将原编号纳入比较键。排序只建立顺序，不能代替贪心策略的正确性证明。

### 从零讲：图的表示、BFS 与 DFS

图由顶点与边组成，适合表达“哪些对象之间能一步到达”。有向边只允许一个方向；无向边需保存两个方向。邻接表 `vector<vector<int>> graph(n)` 为每个顶点保存邻居，空间 $O(n+m)$，无向边在表中出现两次。

以边 $0-1,0-2,1-3$ 为例，从零出发：

![BFS 按距离分层，DFS 沿一条分支深入再返回](assets/foundations/graphs.svg)

#### BFS 为什么得到最少边数

初始顶点距离为零，入先进先出的队列。弹出顶点时，将尚未到达的邻居距离设为当前距离加一，并立刻标记入队。距离为一的顶点都会先于距离为二的处理，因此第一次发现就是最少边数。

```cxx
vector<int> distance(n, -1);
queue<int> q;
distance[start] = 0; q.push(start);
while (!q.empty()) {
    int u = q.front(); q.pop();
    for (int v : graph[u]) if (distance[v] == -1) {
        distance[v] = distance[u] + 1;
        q.push(v);
    }
}
```

适用于无权或所有边代价相同的最少步数。边权不同，第一次发现未必费用最小，不能继续套这一结论。多起点 BFS 先把所有合法起点设零并入队。

#### DFS 的调用代表一整块未探索区域

DFS 标记当前点后，递归处理每个尚未访问的邻点；也可用显式栈。上例可能按 $0,1,3,2$ 的顺序深入，但顺序取决于邻居存放方式。它擅长检查连通性、处理子树和回溯，不保证最短路径。

两种遍历在每个顶点入队或调用一次、每条边检查常数次的实现下，时间均为 $O(n+m)$，额外标记和队列/栈为 $O(n)$。不要等出队才首次标记，否则同一顶点可能重复入队。图不连通时，从一个起点无法覆盖所有点；统计连通块应从每个尚未访问点再启动一次遍历。树的深递归可能用尽调用栈。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：整数类型、整除与溢出

计算前先看每一步可能达到的范围。常见环境中 `int` 是 32 位，上界约 $2.1\times10^9$；`long long` 至少 64 位，常见有符号 64 位上界约 $9.22\times10^{18}$。`using ll = long long;` 只是为已有类型起别名。

```cxx
int a = 100000, b = 100000;
long long wrong = a * b;      // 右边先按 int 乘，可能已溢出
long long right = 1LL * a * b; // 先把运算提升到 long long
```

不能指望“接收结果的变量够大”修复此前已经溢出的计算。先提高操作数类型，再做乘法。超过 64 位时，GCC 的 `__int128` 可作中间量，但它不是标准 C++17 类型，也没有标准流输出重载；先证明范围，再选择工具。

整数 `/` 对有符号数向零截断：`7/3==2`、`-7/3==-2`。对非负数才等于向下取整。余数满足 `a == (a/b)*b + a%b`，除数不能为零；要将余数归入 $[0,m-1]$（$m>0$），可用 `(a % m + m) % m`，同时保证中间加法不溢出。

非负 $a$、正 $b$ 的向上取整可写 `a/b + (a%b != 0)`，比 `(a+b-1)/b` 更容易避免加法溢出。比较平方时也应在宽类型内计算；浮点数不适合作为大整数相等的默认判断方式。

`size()` 返回无符号类型。空容器上写 `size()-1` 会绕到很大的数，逆序遍历可以先转成有符号、确认长度，或使用逆向迭代器。`abs` 对最小有符号数无法在同类型中表达其正值，需先约束输入差值范围。一般机器整数运算按常数时间估算，宽类型解决表示范围，不改变算法的增长阶。

