```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        long long la, ra, lb, rb;
        cin >> la >> ra >> lb >> rb;
        long long L = la + lb, R = ra + rb;
        int answer = 0;
        if (R - L >= 9)
            answer = 9;
        else
            for (long long x = L; x <= R; ++x)
                for (long long y = x; y; y /= 10)
                    answer = max(answer, int(y % 10));
        cout << answer << '\n';
    }
}
```

