### 思路

#### 固定用了多少辆车

设一共用了 $q\ge1$ 辆车，起步价共 $qA$。先尽量把每辆车包含的 $X$ 米用完，剩余付费距离为

$$R=\max(0,D-qX).$$

如果起步里程已经足够，就不需要再付单位价。否则每辆车还有 $Y$ 米的 $B$ 段，以及不限长的 $C$ 段。接下来要决定如何分配这 $R$ 米。

#### 按两种单位价的大小分情况

若 $B\le C$，每一米便宜的 $B$ 段都应先用。全部车合计有 $qY$ 米，因而固定车数的最优费为

$$F(q)=qA+B\min(R,qY)+C\max(0,R-qY).$$

若 $B>C$，需要尽量少跨过昂贵的 $B$ 段。把所有付费距离集中在同一辆车，就至多跨过一个 $Y$ 米的门槛，其余车只使用起步里程。固定车数的最优费为

$$F(q)=qA+B\min(R,Y)+C\max(0,R-Y).$$

为什么集中更好？两辆车若都在付费，可以将其中一辆的付费距离移到另一辆；这样不会多用昂贵的 $B$ 段，超过门槛的距离反而按更便宜的 $C$ 计价。反复合并即可。

使用尽量多的已付起步里程总不会变差，因为剩余的单位价均为正。哪怕车辆起步里程没全部用满，支付全部起步价的公式仍然表示一个可行方案。

#### 不需要枚举巨大车数

将 $R=D-qX$ 代回，固定车数费用是若干条关于 $q$ 的直线。在线性段内部，最小值一定在整数区间端点附近。

所有转折来源只有：

- 起步里程刚好覆盖全程：$q=D/X$。
- 当 $B\le C$，全部 $B$ 段刚好覆盖余程：$q=D/(X+Y)$。
- 当 $B>C$，集中在一车的余程刚好为 $Y$：$q=(D-Y)/X$。

此外车数下界为一，超过起步里程覆盖全程后，费用 $qA$ 只会增加。因此只须检查一，以及这些正转折的向下取整与再加一，负或零车数跳过。

即使把两个分支的所有转折一并放进候选，也只是多做几次计算，代码更直接。这种按车数推导的写法也自然覆盖“最后一辆车的起步里程让前面一部分昂贵路程退回”的边界情况。

#### 大整数实现

数值不能放入 64 位，更不能转浮点比较平均价。代码用十亿为一块保存非负整数，实现进位加法、借位减法、逐块乘法；长除法按高位到低位处理，并在零至十亿减一之间二分每一块的商。除数仅一块时直接逐块求商。所有减法都先保证左侧不小于右侧，除法得到的整数商恰好用于候选车数。每组只需常数次高精度运算，不需要额外库。

设输入最大位数为 $L$，用平方级四则运算估计，时间上界 $O(L^2)$，所需数字存储 $O(L)$。输出最多约两倍输入位数。只付一辆车、单位价相等、起步价极小、$D<X$ 等情况都由相同公式处理。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
struct Big {
    static constexpr int BASE = 1000000000;
    vector<int> digit;
    Big(unsigned long long value = 0) {
        while (value) {
            digit.push_back(value % BASE);
            value /= BASE;
        }
    }
    void trim() {
        while (!digit.empty() && digit.back() == 0)
            digit.pop_back();
    }
    friend bool operator<(const Big &a, const Big &b) {
        if (a.digit.size() != b.digit.size())
            return a.digit.size() < b.digit.size();
        for (int i = int(a.digit.size()) - 1; i >= 0; --i)
            if (a.digit[i] != b.digit[i])
                return a.digit[i] < b.digit[i];
        return false;
    }
    friend Big operator+(const Big &a, const Big &b) {
        Big result;
        int n = max(a.digit.size(), b.digit.size());
        result.digit.resize(n + 1);
        long long carry = 0;
        for (int i = 0; i < n; ++i) {
            long long value = carry;
            if (i < int(a.digit.size()))
                value += a.digit[i];
            if (i < int(b.digit.size()))
                value += b.digit[i];
            result.digit[i] = value % BASE;
            carry = value / BASE;
        }
        result.digit[n] = carry;
        result.trim();
        return result;
    }
    // 本题所有减法均在左数不小于右数时执行。
    friend Big operator-(const Big &a, const Big &b) {
        Big result = a;
        long long borrow = 0;
        for (int i = 0; i < int(a.digit.size()); ++i) {
            long long value = a.digit[i] - borrow;
            if (i < int(b.digit.size()))
                value -= b.digit[i];
            borrow = value < 0;
            if (borrow)
                value += BASE;
            result.digit[i] = value;
        }
        result.trim();
        return result;
    }
    static Big timesSmall(const Big &a, int value) {
        Big result;
        unsigned long long carry = 0;
        for (int x : a.digit) {
            unsigned long long current = 1ULL * x * value + carry;
            result.digit.push_back(current % BASE);
            carry = current / BASE;
        }
        if (carry)
            result.digit.push_back(carry);
        result.trim();
        return result;
    }
    friend Big operator*(const Big &a, const Big &b) {
        Big result;
        result.digit.resize(a.digit.size() + b.digit.size() + 1);
        for (int i = 0; i < int(a.digit.size()); ++i) {
            unsigned long long carry = 0;
            for (int j = 0; j < int(b.digit.size()) || carry; ++j) {
                unsigned long long value = result.digit[i + j] + carry;
                if (j < int(b.digit.size()))
                    value += 1ULL * a.digit[i] * b.digit[j];
                result.digit[i + j] = value % BASE;
                carry = value / BASE;
            }
        }
        result.trim();
        return result;
    }
    friend Big operator/(const Big &a, const Big &b) {
        Big result, remainder;
        result.digit.resize(a.digit.size());
        if (b.digit.size() == 1) {
            unsigned long long carry = 0;
            for (int i = int(a.digit.size()) - 1; i >= 0; --i) {
                unsigned long long value = carry * BASE + a.digit[i];
                result.digit[i] = value / b.digit[0];
                carry = value % b.digit[0];
            }
        } else {
            // 逐块长除法，在零至BASE-1之间二分当前商块。
            for (int i = int(a.digit.size()) - 1; i >= 0; --i) {
                remainder.digit.insert(remainder.digit.begin(), a.digit[i]);
                remainder.trim();
                if (remainder < b)
                    continue;
                int low = 0, high = BASE - 1;
                while (low < high) {
                    int middle = low + (high - low + 1) / 2;
                    if (!(remainder < timesSmall(b, middle)))
                        low = middle;
                    else
                        high = middle - 1;
                }
                result.digit[i] = low;
                remainder = remainder - timesSmall(b, low);
            }
        }
        result.trim();
        return result;
    }
    friend istream &operator>>(istream &in, Big &a) {
        string text;
        in >> text;
        a.digit.clear();
        for (int end = text.size(); end > 0; end -= 9) {
            int begin = max(0, end - 9);
            a.digit.push_back(stoi(text.substr(begin, end - begin)));
        }
        a.trim();
        return in;
    }
    friend ostream &operator<<(ostream &out, const Big &a) {
        if (a.digit.empty())
            return out << 0;
        out << a.digit.back();
        for (int i = int(a.digit.size()) - 2; i >= 0; --i)
            out << setw(9) << setfill('0') << a.digit[i];
        out << setfill(' ');
        return out;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        Big A, B, C, X, Y, D;
        cin >> A >> B >> C >> X >> Y >> D;
        vector<Big> candidates{1};
        auto add = [&](Big q) {
            candidates.push_back(q);
            candidates.push_back(q + 1);
        };
        add(D / X);
        add(D / (X + Y));
        if (Y < D)
            add((D - Y) / X);
        Big answer;
        bool hasAnswer = false;
        for (const Big &q : candidates) {
            if (q < 1)
                continue;
            Big included = q * X, remaining;
            if (included < D)
                remaining = D - included;
            Big capacity = (!(C < B) ? q * Y : Y);
            Big first = (remaining < capacity ? remaining : capacity);
            Big cost = q * A + B * first + C * (remaining - first);
            if (!hasAnswer || cost < answer) {
                answer = cost;
                hasAnswer = true;
            }
        }
        cout << answer << '\n';
    }
    return 0;
}
```

### 易错点

六个数都可能超过64位，不能读入普通整数。换车需要重新支付起步价。分支看B和C大小，车数不能为零。候选包含转折左右两侧，余程取不小于零。

