```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int tests;
    cin >> tests;
    while (tests--) {
        int n;
        cin >> n;
        vector<int> a(n), p(n + 1);
        for (int &x : a)
            cin >> x;
        for (int i = 0, b; i < n; ++i) {
            cin >> b;
            p[a[i]] = b;
        }
        vector<bool> seen(n + 1);
        int cycles = 0;
        for (int i = 1; i <= n; ++i)
            if (!seen[i]) {
                ++cycles;
                for (int u = i; !seen[u]; u = p[u])
                    seen[u] = true;
            }
        int parity = (n - cycles) & 1;
        string answer(1, parity ? 'A' : 'B');
        for (int k = 1; k < n; ++k) {
            char which;
            int l, r, d;
            cin >> which >> l >> r >> d;
            // 两种排列都一样：每次区间左移相当于长度减一次交换。
            parity ^= ((r - l) & 1) & (d & 1);
            answer += parity ? 'A' : 'B';
        }
        cout << answer << '\n';
    }
}
```

### 易错点

后续修改作用于输入排列，并非上一盘游戏结束后的恒等状态。两种排列的换位都翻转相对奇偶性。长度一的区间移位不改变胜负。初始答案也要输出，共输出 $n$ 个字符。

