### 思路

#### 把路径异或看成方程

根点权已知为零，只把二号至末号点作为 $n-1$ 个未知量。一条恰有 $k$ 条边的路径，会将其中经过的未知点权异或起来；用一个位集记录这些点，便得到方程的零一系数。

异或相当于每一位分别对二相加。两条路径方程可以相互异或，左边相同变量会抵消，右边的整型回答也一起异或，所以不必把三十位拆成三十次不同的消元。

#### 问之前就能判断有没有足够信息

枚举每个无序端点对，只有距离恰好为 $k$ 才合法。以每个点为起点做一次 BFS，记录父亲与距离；遇到合法端点，就沿父亲链收集路径上的点，跳过根的已知零。

把这些系数向量插入异或线性基：从高位向低位看，若当前最高的一位已有基向量，就异或消去；遇到空的主元位置，则存下这个新向量，同时保留原始路径端点。全消为零说明这次询问的信息已经能由此前询问表示，无需选择。

若全部路径只能产生少于 $n-1$ 个独立方程，存在非零变量变化量，使每条合法路径的异或都不变。只改一个二进制位就能得到两份不同合法点权，交互器任何回答都无法区分，所以必须 No。

若选出 $n-1$ 个独立方程，未知量已经唯一确定，而且询问数 $n-1\le n$，满足上限。根的已知值从一开始就被删掉，避免最后加一个本来已被路径方程蕴含的条件，却误以为又增加独立信息。

#### 一次询问、一次求解

先输出 Yes，再将全部选定端点放进一行 ? $q$ 后面，刷新输出，然后才读入所有回答。不能每问一条就等回答，因为题目明确要求全部问题先提出。

用保存的原系数向量与对应回答重新做消元。主元取最高位，所以每条主元行只包含比主元更低的未知量。从低主元开始回代，右边再异或已求出的低位点权，就得到当前点权。最后输出二号至末号点的答案并刷新。

路径枚举与收集花 $O(n^3)$，至多 $O(n^2)$ 个向量各与至多 $n$ 个、长度约 $n/64$ 的位集异或，花 $O(n^4/64)$。存选中路径与基向量需 $O(n^2/64+n)$ 空间。全部计算精确，不使用随机询问。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using Bits = bitset<250>;
int main() {
    int n, k;
    cin >> n >> k;
    vector<vector<int>> g(n);
    for (int i = 1, u, v; i < n; ++i) {
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    int variables = n - 1;
    vector<Bits> basis(variables), original;
    vector<pair<int, int>> queries;
    for (int source = 0; source < n && int(queries.size()) < variables; ++source) {
        vector<int> parent(n, -1), distance(n);
        queue<int> q;
        q.push(source);
        parent[source] = source;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : g[u])
                if (parent[v] < 0) {
                    parent[v] = u;
                    distance[v] = distance[u] + 1;
                    q.push(v);
                }
        }
        for (int target = source + 1; target < n && int(queries.size()) < variables; ++target)
            if (distance[target] == k) {
                Bits row;
                for (int u = target;; u = parent[u]) {
                    if (u)
                        row.set(u - 1);
                    if (u == source)
                        break;
                }
                Bits reduced = row;
                for (int pivot = variables - 1; pivot >= 0; --pivot)
                    if (reduced[pivot]) {
                        if (basis[pivot].any())
                            reduced ^= basis[pivot];
                        else {
                            basis[pivot] = reduced;
                            original.push_back(row);
                            queries.emplace_back(source, target);
                            break;
                        }
                    }
            }
    }
    if (int(queries.size()) < variables) {
        cout << "No" << endl;
        return 0;
    }
    cout << "Yes" << endl;
    cout << "? " << queries.size();
    for (auto [u, v] : queries)
        cout << ' ' << u + 1 << ' ' << v + 1;
    cout << endl;
    fill(basis.begin(), basis.end(), Bits{});
    vector<int> right(variables);
    for (int i = 0; i < variables; ++i) {
        int value;
        if (!(cin >> value) || value < 0)
            return 0;
        Bits row = original[i];
        for (int pivot = variables - 1; pivot >= 0; --pivot)
            if (row[pivot]) {
                if (basis[pivot].any()) {
                    row ^= basis[pivot];
                    value ^= right[pivot];
                } else {
                    basis[pivot] = row;
                    right[pivot] = value;
                    break;
                }
            }
    }
    // 主元是行内最高位，所以从低位开始回代，三十个权值位一起异或。
    vector<int> answer(variables);
    for (int i = 0; i < variables; ++i) {
        answer[i] = right[i];
        for (int j = 0; j < i; ++j)
            if (basis[i][j])
                answer[i] ^= answer[j];
    }
    cout << '!';
    for (int value : answer)
        cout << ' ' << value;
    cout << endl;
}
```

### 易错点

路径长度按边数，异或按点权且包含端点。根点是已知零，不能当额外未知变量。No 时不能发询问。所有问题必须一次性打包输出后再读回答，遇到负数回答应停止。

