            ll count, exponent;
            cin >> count >> exponent;
            items.push_back({exponent, count});
            remaining += count;
        }
        sort(items.rbegin(), items.rend());
        vector<pair<ll, ll>> groups;
        for (auto item : items) {
            if (!groups.empty() && groups.back().first == item.first)
                groups.back().second += item.second;
            else
                groups.push_back(item);
        }
        ll previous = groups[0].first, space = 0, answer = 0;
        for (auto [exponent, count] : groups) {
            ll gap = previous - exponent;
            // 非零空位一旦够给剩余每件物品各留一个位置，容量再也不必增加。
            while (gap > 0 && space > 0 && space < remaining) {
                space *= 2;
                --gap;
            }
            if (space >= remaining)
                break;
            if (count > space) {
                ll extra = (count - space + bags - 1) / bags;
                answer = (answer + extra % MOD * powerTwo(exponent)) % MOD;
                space += extra * bags;
            }
            space -= count;
            remaining -= count;
            previous = exponent;
        }
        cout << answer << '\n';
    }
}
```

### 易错点

指数大，不能直接移位构造重量。空位为零时无需倍增。空位达到剩余物品总数即可结束，包括还未处理的当前种类。先求真实最优容量的增量，再取模累计，不能在模数下比较容量大小。

