```cpp
#include <bits/stdc++.h>
using namespace std;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        int n;
        cin >> n;
        vector<int> position(n + 1);
        for (int i = 0, x; i < n; ++i) {
            cin >> x;
            position[x] = i;
        }
        int answer = 1;
        for (int value = 1; value < n; ++value)
            if (position[value] < position[value + 1])
                ++answer;
        cout << answer << '\n';
    }
}
```

### 易错点

分段的是数值区间，不是输入位置区间。这里不能交替弹两个栈，不能套用普通耐心排序的最小递减子序列数。答案至少一，计数条件是较小值在输入中更早。

