// G. 场地布置
// 题意：题面给出 71 个班级的人数表；读入 n，把前 n 个班级的座位贴打印出来，
//       每行形如 "Class x, Number y"（班级从小到大、班内编号从小到大）。
// 做法：把人数表按班级顺序抄进数组，双重循环输出即可（本题只有 n = 1,10,20,40,71）。
//       表格是 4 组列：第 1 列 1~20 班、第 2 列 21~40、第 3 列 41~60、第 4 列 61~71。
#include <bits/stdc++.h>
using namespace std;

int main() {
    // cnt[c] = 第 c 个班级的人数（c = 1..71）
    static const int cnt[72] = {
        0,
        99, 9, 23, 27, 92, 27, 64, 70, 33, 94,        // 1~10
        114, 101, 114, 54, 120, 32, 65, 92, 89, 110,  // 11~20
        78, 25, 82, 14, 54, 99, 100, 62, 76, 46,      // 21~30
        78, 60, 34, 98, 102, 16, 34, 81, 45, 60,      // 31~40
        68, 63, 26, 56, 50, 11, 85, 104, 100, 38,     // 41~50
        49, 85, 91, 17, 100, 43, 59, 18, 116, 77,     // 51~60
        71, 74, 57, 119, 41, 104, 57, 87, 38, 120, 52 // 61~71
    };

    int n;
    cin >> n;
    string out;                                   // 一次性拼好再输出，快一些
    for (int c = 1; c <= n; c++)
        for (int k = 1; k <= cnt[c]; k++)
            out += "Class " + to_string(c) + ", Number " + to_string(k) + "\n";
    cout << out;
