### 参考代码

```cpp
// D. Kendieer 的 LCP 问题
// 做法：建 trie。一次询问的答案 = Σ_{trie 非根节点 v} (2^{cnt_v} - 1)，
// 其中 cnt_v = 该次询问选中的串里，经过节点 v 的个数（即子树内的选中串数）。
// 因为每个非空子集 T 的 LCP 长度 = 「T 中所有串都经过的节点数」，
// 而对固定节点 v，含 v 却没被算到的子集恰是全部选中串都在 v 子树里的那 2^{cnt_v}-1 个。
// 逐节点枚举做不到（路径总长可到 5e5 × 5e5），于是把选中串的终止节点按 dfs 序排序，
// 建虚树（LCA 闭包 + 单调栈），虚树节点上的 cnt 用「孩子往上累加」求出，
// 每条虚树边 (a,b) 覆盖深度 dep_a+1..dep_b 的一整段链，这段链上每个节点的 cnt 都等于 cnt_b，
// 所以贡献 = (dep_b - dep_a) × (2^{cnt_b} - 1)。
#include <bits/stdc++.h>
using namespace std;

static const int MOD = 998244353;

static int LOGN;                     // 倍增层数
static int nsz;                      // 当前测试数据的 trie 节点数
static vector<int> par, depv, tin, sz, termn, cntv, vpar;
static vector<int> head, nxt, to;    // 孩子链表（head[v] 指向边编号，-1 表示没有孩子）
static vector<int> up;               // 倍增祖先，扁平存：up[k * nsz + v]
static vector<int> pw2;              // 2 的幂（模 MOD）

// a 是否是 b 的祖先（含 a == b）：dfs 序区间判定
static inline bool isAnc(int a, int b) {
    return tin[a] <= tin[b] && tin[b] < tin[a] + sz[a];
}

// 倍增求 LCA
static int lca(int a, int b) {
    if (depv[a] < depv[b]) swap(a, b);
    int d = depv[a] - depv[b];
    for (int k = 0; d; ++k, d >>= 1) {          // 先把 a 提到与 b 同深度
        if (d & 1) a = up[(size_t)k * nsz + a];
    }
    if (a == b) return a;
    for (int k = LOGN - 1; k >= 0; --k) {       // 一起往上跳，跳到 LCA 的儿子层
        int ua = up[(size_t)k * nsz + a], ub = up[(size_t)k * nsz + b];
        if (ua != ub) { a = ua; b = ub; }
    }
    return up[a];                               // 再跳一步就是 LCA
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    pw2.assign(500005, 1);                      // k <= n <= 1e5，留足余量
    for (int i = 1; i < (int)pw2.size(); ++i) pw2[i] = (int)(2LL * pw2[i - 1] % MOD);

    int T;
    cin >> T;
    while (T--) {
        int n, q;
        cin >> n >> q;
        vector<string> s(n);
        for (int i = 0; i < n; ++i) cin >> s[i];

        // 按下标字典序排序：这样插入 trie 时不必查孩子表——
        // 与上一个串的公共前缀路径已经存在，剩下的部分全是新建节点。
        vector<int> ord(n);
        iota(ord.begin(), ord.end(), 0);
        sort(ord.begin(), ord.end(), [&](int a, int b) { return s[a] < s[b]; });

        // ---------- 建 trie ----------
        nsz = 1;                                // 节点 0 是根
        par.assign(1, 0); depv.assign(1, 0); head.assign(1, -1);
        nxt.clear(); to.clear();
        termn.assign(n, 0);
        vector<int> path(1, 0);                 // path[d] = 上一个串在深度 d 处的节点
        int prevIdx = -1;                       // 上一个插入的串（在 s 中的下标）
        for (int oi = 0; oi < n; ++oi) {
            int idx = ord[oi];
            const string &cur = s[idx];
            int len = (int)cur.size();
            int l = 0;
            if (prevIdx >= 0) {                 // 与上一个串的最长公共前缀长度
                const string &pv = s[prevIdx];
                int lim = (int)min(pv.size(), cur.size());
                while (l < lim && pv[l] == cur[l]) ++l;
            }
            if ((int)path.size() < len + 1) path.resize(len + 1);
            for (int d = l + 1; d <= len; ++d) {// 从浅到深新建节点，path[d-1] 必然已就绪
                int v = nsz++;
                par.push_back(path[d - 1]);
                depv.push_back(d);              // 深度 = 前缀长度
                head.push_back(-1);
                nxt.push_back(head[path[d - 1]]);
                to.push_back(v);
                head[path[d - 1]] = (int)to.size() - 1;
                path[d] = v;
            }
            termn[idx] = path[len];             // 该串的终止节点
            prevIdx = idx;                      // 注意：记的是 s 里的下标，不是排序后的名次
        }

        // ---------- 迭代 dfs：求 tin 与子树大小 ----------
        tin.assign(nsz, 0); sz.assign(nsz, 0);
        {
            vector<int> it(head), stk;
            stk.reserve(nsz);
            int timer = 0;
            tin[0] = timer++;
            stk.push_back(0);
            while (!stk.empty()) {
                int v = stk.back();
                int e = it[v];
                if (e == -1) {                  // 孩子走完了，子树区间定下来
                    sz[v] = timer - tin[v];
                    stk.pop_back();
                    continue;
                }
                it[v] = nxt[e];                 // 下一条孩子边
                int u = to[e];
                tin[u] = timer++;
                stk.push_back(u);
            }
        }

        // ---------- 倍增祖先表 ----------
        int maxd = 1;
        for (int v = 0; v < nsz; ++v) maxd = max(maxd, depv[v]);
        LOGN = 1;
        while ((1 << LOGN) <= maxd) ++LOGN;
        up.assign((size_t)LOGN * nsz, 0);
        for (int v = 0; v < nsz; ++v) up[v] = par[v];   // 根的 par 记 0（自己是自己的祖先）
        for (int k = 1; k < LOGN; ++k) {
            for (int v = 0; v < nsz; ++v) {
                int mid = up[(size_t)(k - 1) * nsz + v];
                up[(size_t)k * nsz + v] = up[(size_t)(k - 1) * nsz + mid];
            }
        }

        cntv.assign(nsz, 0);                    // 只在用到的节点上赋值
        vpar.assign(nsz, 0);

        // ---------- 处理询问 ----------
        vector<int> nodes, uni, w, cand, ordv, vstk;
        for (int qi = 0; qi < q; ++qi) {
            int k;
            cin >> k;
            nodes.resize(k);
            for (int j = 0; j < k; ++j) {
                int idx;
                cin >> idx;
                nodes[j] = termn[idx - 1];
            }
            sort(nodes.begin(), nodes.end(), [&](int a, int b) { return tin[a] < tin[b]; });

            uni.clear(); w.clear();             // 去重（同一串被多次选中要按次数计权）
            for (int u : nodes) {
                if (!uni.empty() && uni.back() == u) ++w.back();
                else { uni.push_back(u); w.push_back(1); }
            }

            cand.clear();                       // LCA 闭包 = 终止节点 ∪ 相邻两项的 LCA
            for (int u : uni) cand.push_back(u);
            for (size_t i = 0; i + 1 < uni.size(); ++i) cand.push_back(lca(uni[i], uni[i + 1]));
            cand.push_back(0);                  // 根也要进来
            sort(cand.begin(), cand.end(), [&](int a, int b) { return tin[a] < tin[b]; });
            cand.erase(unique(cand.begin(), cand.end()), cand.end());

            for (int v : cand) cntv[v] = 0;
            for (size_t i = 0; i < uni.size(); ++i) cntv[uni[i]] = w[i];

            // 闭包内按 dfs 序扫一遍，用「祖先判定 + 栈」直接得到虚树的父亲
            vstk.assign(1, 0);                  // cand[0] 一定是根（tin 最小）
            for (size_t i = 1; i < cand.size(); ++i) {
                int v = cand[i];
                while (!isAnc(vstk.back(), v)) vstk.pop_back();
                vpar[v] = vstk.back();
                vstk.push_back(v);
            }

            // 按深度从大到小累加 cnt（孩子全部处理完才轮到父亲），顺手算贡献
            ordv = cand;
            sort(ordv.begin(), ordv.end(), [&](int a, int b) { return depv[a] > depv[b]; });
            long long ans = 0;
            for (int v : ordv) {
                if (v == 0) continue;           // 根不贡献（深度 0 不计入 LCP）
                int c = cntv[v];
                int term = pw2[c] - 1;
                if (term < 0) term += MOD;
                ans = (ans + (long long)(depv[v] - depv[vpar[v]]) * term) % MOD;
                cntv[vpar[v]] += c;
            }
            if (qi) cout << ' ';
            cout << ans;
        }
        cout << '\n';
    }
    return 0;
}
```

### 易错点

不能把同一终点的多个选中下标去重成一个方案。根代表空前缀，长度为零，不单独贡献。

## B. 「LAOI-19」新建题目

### 题意

给定零一矩阵。序列的零位与每一行的零位至少相交一次时为好序列；坏序列的邪恶度是翻转后能使它变好的位置数，求最大邪恶度。

<!-- reusable-foundations:start -->

### 从零讲：枚举与模拟：让代码和允许的动作一一对应

枚举是系统地检查所有候选；模拟是按题目规则推进状态。先写清一个候选是什么、有哪些动作、执行后哪些量改变，再决定循环边界。

例如从集合 $\{1,2,3\}$ 中选两个不同数：有序选择可枚举 $(i,j)$ 且 $i\ne j$，共六项；如果只关心无序的一对，就规定 $i<j$，得到 $(1,2)$、$(1,3)$、$(2,3)$，避免重复计数。同一个双循环，边界表达的是不同对象。

```cxx
for (int i = 0; i < n; ++i)
    for (int j = i + 1; j < n; ++j) {
        // 每一对不同位置恰好出现一次
    }
```

模拟例如计数器初始为零，依次读动作“加二、减一、加二”，状态为 $0\to2\to1\to3$。每一步都只读取该时刻允许的信息；若规则要求同时更新多个量，应先用旧状态算全部新量，不能让后一个更新误读前一个新值。

时间要数实际候选数和每个候选的工作。双循环可能是 $O(n^2)$，枚举长度为 $k$ 的二进制选择是 $O(2^k)$；候选少但每次又扫描全数组，也要乘上扫描成本。空间取决于是否需要保存历史。

全枚举的优势是思路直接，容易作为独立校验程序。剪枝必须证明被略去的分支不可能合法或更优，不能只因一个小例子没遇到答案就删候选。若直接枚举超时，先找重复工作、对称性、可维护的量或单调边界，再选择优化方法。

### 从零讲：位运算：把非负整数看成一组二进制开关

五写成二进制为 $0101_2$，三为 $0011_2$。同一列各代表一位：按位与 `&` 两边都为一才得一，按位或 `|` 任一为一就得一，按位异或 `^` 不同才为一。所以 $5\mathbin{\&}3=1$，$5\mathbin{|}3=7$，$5\mathbin{\oplus}3=6$。

![相同数值分别写成每一位，逐列计算与、或、异或](assets/foundations/bits.svg)

`1ULL << k` 把一移到第 $k$ 位。对非负无符号整数，`(mask >> k) & 1ULL` 读该位，`mask | (1ULL<<k)` 置一，`mask & ~(1ULL<<k)` 清零，`mask ^ (1ULL<<k)` 翻转。最低位编号为零。

```cxx
unsigned long long mask = 5; // 第 0、2 位为一
bool has = (mask >> 2) & 1ULL; // true
mask |= 1ULL << 1;             // 变成 7
```

位移次数必须小于类型位宽，且不能为负；不要用普通 `1` 去移到超出 int 范围的位置。C++17 有符号负数右移和溢出的规则不适合直接套“乘除二的幂”，用明确范围的无符号数更容易保证行为。`^` 是异或，绝不是乘方。

逻辑与 `&&`、逻辑或 `||` 将整体条件视为真假，并会短路；按位 `&`、`|` 逐位计算，不会因此跳过右侧表达式。运算符优先级可能与直觉不同，写 `(mask & bit) != 0`，别省掉关键括号。

固定机器字内的一次位运算按 $O(1)$ 估算；枚举全部 $k$ 位状态仍有 $2^k$ 种，不能因为每次运算快就忽略状态数。`x & (x-1)` 对正无符号数清掉最低的一位；GCC 的 `__builtin_popcountll(x)` 统计一的数量，注意实参位宽与具体编译器支持。

### 从零讲：vector：长度可变的连续数组

`vector<T>` 保存一串同类型的元素，适合按下标访问、扫描、排序。`T` 是元素类型，例如 `vector<int>` 保存整数，`vector<pair<int,int>>` 保存整数对，`vector<vector<int>>` 可保存每个顶点各自的邻居。需要 `<vector>`。

```cxx
vector<int> a(3, 7);   // 三个元素，内容是 7、7、7
a.push_back(9);       // 在末尾追加，现在长度为 4
int x = a[1];         // 从 0 编号，这里得到 7
a[1] = 2;            // 改第二个元素
int n = int(a.size());
```

`vector<int> a(3)` 创建三个值为零的元素；`a.reserve(3)` 只预留容量，元素数仍为零，此时不能访问 `a[0]`。长度 `size()` 与容量 `capacity()` 是不同概念。

下标访问为 $O(1)$，遍历为 $O(n)$。末尾追加通常为 $O(1)$；容量不足时会分配更大的连续空间并搬移元素，这次可能为 $O(n)$，一连串追加的平均成本称为摊还 $O(1)$。中间插入或删除会搬移后续元素，最坏 $O(n)$。内存是元素量的 $O(n)$，并可能预留部分尚未使用的容量。

`begin()` 指向首元素，`end()` 指向尾后位置，`sort(a.begin(),a.end())` 操作整个数组。`a[i]` 不检查越界；下标须满足 $0\le i<\mathrm{size}$。`at(i)` 会检查越界并抛异常。空数组不能访问 `front()`、`back()`；`pop_back()` 也要求非空。

扩容后指向旧存储的迭代器、引用和指针会失效。遍历的同时 `push_back`，不能假定此前取得的引用仍可用。读取大数组的函数常用 `const vector<int>& a` 按常量引用传入，既不复制也禁止通过该引用修改；`vector<int> a` 按值传参则复制内容。选择副本还是引用取决于是否要保留独立数据。

### 从零讲：string：字符、下标与子串

`string` 保存字符序列。`string s="abca";` 的长度为四，下标从零开始，`s[0]=='a'`、`s[3]=='a'`。字符用单引号，字符串用双引号；二者类型不同。需要 `<string>`。

`cin >> s` 读到空白停止；整行含空格时使用 `getline`，并留意前一次格式化输入残留的换行。`s.size()` 是字符单元数量，不一定等于 UTF-8 中文字数；竞赛英文小写字母题通常一个字符对应一个单元。

```cxx
string s = "abca";
string middle = s.substr(1, 2); // 从下标 1 开始取 2 个字符，得到 bc
size_t pos = s.find('c');       // 得到 2；找不到是 string::npos
if (pos != string::npos) cout << s[pos];
```

`substr(start,length)` 的第二项是长度，不是右端点。普通下标访问为 $O(1)$；复制长为 $k$ 的子串需要 $O(k)$ 时间和空间，循环里反复截取可能累积成平方成本。字符串比较按第一个不同字符决定字典序，公共前缀可能需要线性比较。

常见字符转数字是 `c-'0'`，前提 `c` 在 `'0'` 到 `'9'`。修改原串可用 `for(char& c:s)`，只读使用 `char c`。`reverse(s.begin(),s.end())` 原地翻转；若还需要原串，应先复制。空串不能访问首尾，尾后位置不能当普通字符读取。

