### 从零讲：冲突图 + 小候选集搜索

把每个不同集合当作一个结点，相交的两个结点之间有冲突。最终必须删除每条冲突边至少一端。

如果当前发现冲突集合 $A,B$，任何完整解都必须选到 $A\cup B$ 中至少一个值，否则这两个集合会同时留下。虽然所有值的范围很大，但下一步只需从这至多八个候选中分支。每条可行解都能沿某个分支保留，因此这个小候选搜索不会漏解。

### 思路

集合 $\{1,2,3,4\}$ 与 $\{1,5,6,7\}$ 相交又不相等，不能同时保留。任何成功方案都必须选它们并集中的至少一个值，才能删除至少一方；选择并集之外的值对这对冲突没有作用。这个观察把巨大值域上的搜索压成每层至多八个候选。

先把每个集合内部排序，相同集合归为同一组。完全相同的集合允许共存，且选某个值时会一起删除，所以保留一个分组代表就足以检测冲突。

给定当前已选值 sol，扫描所有未被它命中的分组。用每个元素的 owner 记录本次检查中首先占用它的存活分组；若同一元素再次出现在另一个分组中，就找到相交的两个不同集合，构成冲突。若全部扫描完仍无冲突，当前选择已经合法。

#### 为什么只围绕当前冲突分支不会漏解

找到冲突 A、B 后，任何包含当前选择的完整解，都必须进一步选入 $A\cup B$ 中的某个值。否则它们都不会被删除，冲突永久存在。因此对并集每个不同值各开一个分支，总有分支仍然与任意可能的最优解相容。

选择数最多为三，递归深度也只有三。每到一个节点都先检查是否已经合法，即使少于三次也可以结束并记录；若仍有冲突且次数用尽，这条分支失败。没有必要选从未出现的值，因为它不会删除任何集合，只会浪费名额。

合法解之间先比较数量，再把值升序排列后比较字典序。原代码会遍历全部必要分支，而不是遇到第一个解就停止，因此即使分支顺序没有按全局字典序排列，也能选出正确最优方案。空集本身合法时会直接得到零次方案。

实现上先离散化实际出现的元素，用数组维护占用者；seenStamp 用时间戳区分不同冲突检查，省去每次清空整个数组。每层至多八分支，总节点数不超过 $1+8+64+512$，每次只线性扫描分组，因而能承受较大集合数量。

### 参考代码

```cpp
// B. 鱼 —— 冲突对必须被 D 打掉：每层只在 A_i∪A_j（≤8 个）里扩一个元素，深度 ≤3
// 把所有分支能得到的合法 D 都收集起来，按 (|D|, 字典序) 取最优
#include <bits/stdc++.h>
using namespace std;

int n;
long long k;
vector<array<long long, 4>> rawSets;   // 每个集合原始 4 值（已排序），下标 = 集合编号
vector<array<int, 4>> gElems;           // 每个「同集合」分组的 4 个元素（压缩序号）
vector<vector<int>> gSets;              // 每个分组包含哪些集合下标
unordered_map<long long, int> vid;      // 原始值 -> 压缩序号
vector<int> seenStamp, ownerG;          // 元素本次检查是否登记过 / 登记它的分组号
int stamp = 0;
vector<long long> sol;                  // 当前正在构造的 D
vector<long long> bestD;
bool hasBest = false;

// 未删除集合里是否有冲突；有则给出两个代表集合下标 ra、rb（分属两个不同的分组）
bool findConflict(int &ra, int &rb) {
    ++stamp;
    int sc[3], scn = 0;
    for (size_t d = 0; d < sol.size(); ++d) sc[scn++] = vid[sol[d]];
    for (int g = 0; g < (int)gElems.size(); ++g) {
        bool hit = false;                                    // 该分组是否被 D 打中
        for (int t = 0; t < 4 && !hit; ++t)
            for (int q = 0; q < scn; ++q)
                if (gElems[g][t] == sc[q]) { hit = true; break; }
        if (hit) continue;
        for (int t = 0; t < 4; ++t) {                        // 登记未删除分组的元素
            int e = gElems[g][t];
            if (seenStamp[e] == stamp) {                     // 已被别的未删分组占用 -> 冲突
                if (ownerG[e] != g) {
                    ra = gSets[ownerG[e]][0];
                    rb = gSets[g][0];
                    return true;
                }
            } else {
                seenStamp[e] = stamp;
                ownerG[e] = g;
            }
        }
    }
    return false;
}

bool better(const vector<long long> &a, const vector<long long> &b) {  // a 是否优于 b
    if (a.size() != b.size()) return a.size() < b.size();             // 先最小化 |D|
    return a < b;                                                      // 再字典序最小
}

void dfs(int depth) {
    int a, b;
    if (!findConflict(a, b)) {                     // sol 已是合法 D
        vector<long long> c = sol;
        sort(c.begin(), c.end());
        if (!hasBest || better(c, bestD)) { bestD = c; hasBest = true; }
        return;
    }
    if (depth == 3) return;                        // |D| 上限 3
    long long cand[8];
    int cn = 0;                                    // 候选 = A_a ∪ A_b
    for (int t = 0; t < 4; ++t) cand[cn++] = rawSets[a][t];
    for (int t = 0; t < 4; ++t) {
        long long v = rawSets[b][t];
        bool dup = false;
        for (int i = 0; i < cn; ++i) if (cand[i] == v) { dup = true; break; }
        if (!dup) cand[cn++] = v;
    }
    for (int i = 0; i < cn; ++i) {
        long long v = cand[i];
        bool inSol = false;
        for (size_t j = 0; j < sol.size(); ++j) if (sol[j] == v) inSol = true;
        if (inSol) continue;
        sol.push_back(v);
        dfs(depth + 1);
        sol.pop_back();
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int T;
    cin >> T;
    while (T--) {
        cin >> n >> k;
        rawSets.assign(n, {});
        vector<long long> vals;
        vals.reserve(4 * n);
        for (int i = 0; i < n; ++i) {
            array<long long, 4> a{};
            for (int j = 0; j < 4; ++j) cin >> a[j];
            sort(a.begin(), a.end());
            rawSets[i] = a;
            for (int j = 0; j < 4; ++j) vals.push_back(a[j]);
        }
        sort(vals.begin(), vals.end());
        vals.erase(unique(vals.begin(), vals.end()), vals.end());
        vid.clear();
        vid.reserve(vals.size() * 2);
        for (size_t i = 0; i < vals.size(); ++i) vid[vals[i]] = (int)i;

        map<array<long long, 4>, int> gid;   // 相同集合归为一个分组
        gElems.clear();
        gSets.clear();
        for (int i = 0; i < n; ++i) {
            auto it = gid.find(rawSets[i]);
            int g;
            if (it == gid.end()) {
                g = (int)gElems.size();
                gid[rawSets[i]] = g;
                array<int, 4> key{};
                for (int j = 0; j < 4; ++j) key[j] = vid[rawSets[i][j]];
                gElems.push_back(key);
                gSets.push_back({});
            } else {
                g = it->second;
            }
            gSets[g].push_back(i);
        }
        seenStamp.assign(vals.size(), 0);
        ownerG.assign(vals.size(), -1);
        stamp = 0;
        sol.clear();
        bestD.clear();
        hasBest = false;
        dfs(0);
        if (!hasBest) {
            cout << "NO\n";
        } else {
            cout << "YES " << bestD.size();
            for (size_t i = 0; i < bestD.size(); ++i) cout << ' ' << bestD[i];
            cout << '\n';
        }
    }
    return 0;
}
```

### 易错点

相同集合本身允许共存，必须去重或在冲突判定时区分。不能找到第一个合法解就停，否则未必满足数量和字典序要求。

## C. 玩具

### 题意

第一条排列已分成若干连续段，只能合并相邻段。要求每段的元素在全部 $k$ 条排列中都连续，最大化最后段数。

