### 参考程序 · C++17

```cpp
#include <bits/stdc++.h>
using namespace std;
int main(){
    ios::sync_with_stdio(false);cin.tie(nullptr);
    int n;cin>>n;vector<long long>a(n),p(n+1),q(n+1);
    for(auto &x:a)cin>>x;
    for(int i=0;i<n;++i)p[i+1]=p[i]+a[i];
