### 思路

逆序恢复位置，激活后与已激活左右邻居合并，根维护连续段总和。逆序第 i 步先记录当前最大和，再恢复第 i 个位置，才能对应正序“删除后”的状态。非负条件保证合并不会使最大值下降。

正向删除一个位置可能把一个连通块拆成两个，并查集不方便处理拆分。倒序处理删除序列：从空数组开始把位置加回来，每次只需与左右已存在位置合并。此时连通块就是未被删除的连续段，根上记录段和。原数组元素非负，所以新增与合并不会让全局最大段和下降，可以只维护 best=max(best,新块段和)。在加回第 i 个位置之前保存 best，它才对应正向完成第 i 次删除后的状态；先加回再保存会整体错位。若题目允许负数，这种只增不减的 best 维护就不再成立。

![倒序加入，把左右段合并](assets/graph-lab/722C.svg)

加入中间位置前两段分离；加入后段和为 5+4+3=12。

#### 亲手推演

数组 [1,3,2,5]，先删位置 3，最大未删除连续段和？

剩下 [1,3] 和 [5]，取 max(4,5)=5。

#### 对应到实现

记录要放在恢复前；恢复后对应的是更早一次删除之后。

```cxx
answer[i] = best; activate(order[i]);
```

### 复杂度

时间 O(nα(n))，空间 O(n)，段和用 long long。

### 参考代码

```cpp
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll INF = (1LL << 62);
struct DSU {
    vector<int> p, sz;
    DSU(int n) : p(n), sz(n, 1) { iota(p.begin(), p.end(), 0); }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b)
            return false;
        if (sz[a] < sz[b])
            swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        return true;
    }
};
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<ll> a(n), sum(n), ans(n);
    for (ll &x : a)
        cin >> x;
    vector<int> order(n);
    for (int &x : order) {
        cin >> x;
        --x;
    }
    DSU d(n);
    vector<bool> active(n);
    ll best = 0;
    for (int i = n - 1; i >= 0; i--) {
        ans[i] = best;
        int u = order[i];
        active[u] = true;
        sum[u] = a[u];
        for (int v : {u - 1, u + 1})
            if (v >= 0 && v < n && active[v]) {
                int x = d.find(u), y = d.find(v);
                ll total = sum[x] + sum[y];
                if (d.unite(x, y))
                    sum[d.find(u)] = total;
            }
        best = max(best, sum[d.find(u)]);
    }
    for (ll x : ans)
        cout << x << '\n';
}
```

